export function SkipCopyingMetatileFromSavedMap(mapBlock: any, mapWidth: any, yMode: any): any {
  if (yMode == 0xFF)
          return FALSE;

      if (yMode == 0)
          mapBlock -= mapWidth;
      else
          mapBlock += mapWidth;

      if (IsLargeBreakableDecoration(UNPACK_METATILE(mapBlock), yMode) == TRUE)
          return TRUE;
      return FALSE;
}

/** static void CopyTilesetToVram(struct Tileset const *tileset, u16 numTiles, u16 offset) */
export function CopyTilesetToVram(tileset: any, numTiles: any, offset: any): any {
  if (tileset)
      {
          if (!tileset.isCompressed)
              LoadBgTiles(2, tileset.tiles, numTiles * 32, offset);
          else
              DecompressAndCopyTileDataToVram(2, tileset.tiles, numTiles * 32, offset, 0);
      }
}

/** static void CopyTilesetToVramUsingHeap(struct Tileset const *tileset, u16 numTiles, u16 offset) */
export function CopyTilesetToVramUsingHeap(tileset: any, numTiles: any, offset: any): any {
  if (tileset)
      {
          if (!tileset.isCompressed)
              LoadBgTiles(2, tileset.tiles, numTiles * 32, offset);
          else
              DecompressAndLoadBgGfxUsingHeap(2, tileset.tiles, numTiles * 32, offset, 0);
      }
}

/** static void LoadTilesetPalette(struct Tileset const *tileset, u16 destOffset, u16 size) */
export function LoadTilesetPalette(tileset: any, destOffset: any, size: any): any {
  let black: any = RGB_BLACK;

      if (tileset)
      {
          if (tileset.isSecondary == FALSE)
          {
              LoadPalette(black, destOffset, PLTT_SIZEOF(1));
              LoadPalette(tileset.palettes[0] + 1, destOffset + 1, size - PLTT_SIZEOF(1));
              ApplyGlobalTintToPaletteEntries(destOffset + 1, (size - PLTT_SIZEOF(1)) >> 1);
          }
          else if (tileset.isSecondary == TRUE)
          {
              LoadPalette(tileset.palettes[NUM_PALS_IN_PRIMARY], destOffset, size);
              ApplyGlobalTintToPaletteEntries(destOffset, size >> 1);
          }
          else
          {
              LoadCompressedPalette(tileset.palettes, destOffset, size);
              ApplyGlobalTintToPaletteEntries(destOffset, size >> 1);
          }
      }
}

/** void CopyPrimaryTilesetToVram(struct MapLayout const *mapLayout) */
export function CopyPrimaryTilesetToVram(mapLayout: any): any {
  CopyTilesetToVram(mapLayout.primaryTileset, NUM_TILES_IN_PRIMARY, 0);
}

/** void CopySecondaryTilesetToVram(struct MapLayout const *mapLayout) */
export function CopySecondaryTilesetToVram(mapLayout: any): any {
  CopyTilesetToVram(mapLayout.secondaryTileset, NUM_TILES_TOTAL - NUM_TILES_IN_PRIMARY, NUM_TILES_IN_PRIMARY);
}

/** void CopySecondaryTilesetToVramUsingHeap(struct MapLayout const *mapLayout) */
export function CopySecondaryTilesetToVramUsingHeap(mapLayout: any): any {
  CopyTilesetToVramUsingHeap(mapLayout.secondaryTileset, NUM_TILES_TOTAL - NUM_TILES_IN_PRIMARY, NUM_TILES_IN_PRIMARY);
}

/** static void LoadPrimaryTilesetPalette(struct MapLayout const *mapLayout) */
export function LoadPrimaryTilesetPalette(mapLayout: any): any {
  LoadTilesetPalette(mapLayout.primaryTileset, BG_PLTT_ID(0), NUM_PALS_IN_PRIMARY * PLTT_SIZE_4BPP);
}

/** void LoadSecondaryTilesetPalette(struct MapLayout const *mapLayout) */
export function LoadSecondaryTilesetPalette(mapLayout: any): any {
  LoadTilesetPalette(mapLayout.secondaryTileset, BG_PLTT_ID(NUM_PALS_IN_PRIMARY), (NUM_PALS_TOTAL - NUM_PALS_IN_PRIMARY) * PLTT_SIZE_4BPP);
}

/** void CopyMapTilesetsToVram(struct MapLayout const *mapLayout) */
export function CopyMapTilesetsToVram(mapLayout: any): any {
  if (mapLayout)
      {
          CopyTilesetToVramUsingHeap(mapLayout.primaryTileset, NUM_TILES_IN_PRIMARY, 0);
          CopyTilesetToVramUsingHeap(mapLayout.secondaryTileset, NUM_TILES_TOTAL - NUM_TILES_IN_PRIMARY, NUM_TILES_IN_PRIMARY);
      }
}

/** void LoadMapTilesetPalettes(struct MapLayout const *mapLayout) */
export function LoadMapTilesetPalettes(mapLayout: any): any {
  if (mapLayout)
      {
          LoadPrimaryTilesetPalette(mapLayout);
          LoadSecondaryTilesetPalette(mapLayout);
      }
}

